-- B061 baseline: the platform as V001 to V061 leave it, created directly in one schema.
-- Generated by infrastructure/consolidation/make_baseline.py from a database built by those migrations, and
-- checked against one (same objects, columns, keys, defaults, policies, grants). Used only for a NEW environment
-- (empty ledger); the deploy then records V001 to V061 as applied. Existing environments apply
-- snowflake/database/migrations/archive/ instead. Never edit: changes go into a new migration (V062 on).

-- ---------------------------------------------------------------- database roles
CREATE DATABASE ROLE IF NOT EXISTS {{database}}.DATA_ENGINEER COMMENT = 'Create and drive onboarding runs';
CREATE DATABASE ROLE IF NOT EXISTS {{database}}.DATA_STEWARD COMMENT = 'Reviewer with access to unmasked profile samples';
CREATE DATABASE ROLE IF NOT EXISTS {{database}}.DOMAIN_OWNER COMMENT = 'Reviewer and owner of domain knowledge';
CREATE DATABASE ROLE IF NOT EXISTS {{database}}.OPS_SERVICE COMMENT = 'Write Airflow runs, events and job leases';
CREATE DATABASE ROLE IF NOT EXISTS {{database}}.OPS_VIEWER COMMENT = 'Read Airflow runs captured for ops';
CREATE DATABASE ROLE IF NOT EXISTS {{database}}.PLATFORM_ADMIN COMMENT = 'Platform operations';
CREATE DATABASE ROLE IF NOT EXISTS {{database}}.QA_ENGINEER COMMENT = 'Write and run QA tests, work Jira issues';
CREATE DATABASE ROLE IF NOT EXISTS {{database}}.REVIEWER COMMENT = 'Approve or reject human review gates';
CREATE DATABASE ROLE IF NOT EXISTS {{database}}.SERVICE_AGENT COMMENT = 'Cortex Agent tool execution identity';
CREATE DATABASE ROLE IF NOT EXISTS {{database}}.VIEWER COMMENT = 'Read platform metadata';
GRANT DATABASE ROLE {{database}}.OPS_SERVICE TO DATABASE ROLE {{database}}.DATA_ENGINEER;
GRANT DATABASE ROLE {{database}}.QA_ENGINEER TO DATABASE ROLE {{database}}.DATA_ENGINEER;
GRANT DATABASE ROLE {{database}}.VIEWER TO DATABASE ROLE {{database}}.DATA_ENGINEER;
GRANT DATABASE ROLE {{database}}.REVIEWER TO DATABASE ROLE {{database}}.DATA_STEWARD;
GRANT DATABASE ROLE {{database}}.REVIEWER TO DATABASE ROLE {{database}}.DOMAIN_OWNER;
GRANT DATABASE ROLE {{database}}.OPS_VIEWER TO DATABASE ROLE {{database}}.OPS_SERVICE;
GRANT DATABASE ROLE {{database}}.VIEWER TO DATABASE ROLE {{database}}.OPS_SERVICE;
GRANT DATABASE ROLE {{database}}.DATA_ENGINEER TO DATABASE ROLE {{database}}.PLATFORM_ADMIN;
GRANT DATABASE ROLE {{database}}.DATA_STEWARD TO DATABASE ROLE {{database}}.PLATFORM_ADMIN;
GRANT DATABASE ROLE {{database}}.DOMAIN_OWNER TO DATABASE ROLE {{database}}.PLATFORM_ADMIN;
GRANT DATABASE ROLE {{database}}.SERVICE_AGENT TO DATABASE ROLE {{database}}.PLATFORM_ADMIN;
GRANT DATABASE ROLE {{database}}.VIEWER TO DATABASE ROLE {{database}}.QA_ENGINEER;
GRANT DATABASE ROLE {{database}}.VIEWER TO DATABASE ROLE {{database}}.REVIEWER;
GRANT DATABASE ROLE {{database}}.VIEWER TO DATABASE ROLE {{database}}.SERVICE_AGENT;
GRANT DATABASE ROLE {{database}}.OPS_VIEWER TO DATABASE ROLE {{database}}.VIEWER;

-- ---------------------------------------------------------------- schemas
CREATE SCHEMA IF NOT EXISTS {{database}}.CORE COMMENT = 'Workflow state machine, runs, reviews';
CREATE SCHEMA IF NOT EXISTS {{database}}.GDP_SILVER COMMENT = 'Development target schema of generated GDP dbt models (compiled only in Phase 1)';
CREATE SCHEMA IF NOT EXISTS {{database}}.LANDING COMMENT = 'As-is landing (bronze) of onboarded source objects; one table per source object';

-- ---------------------------------------------------------------- sequences
CREATE SEQUENCE IF NOT EXISTS {{database}}.CORE.CASE_SEQ start with 1 increment by 1 noorder;
CREATE SEQUENCE IF NOT EXISTS {{database}}.CORE.SEQ_INGESTION_CHILD_ID start with 1 increment by 1 noorder;
CREATE SEQUENCE IF NOT EXISTS {{database}}.CORE.SEQ_INGESTION_MASTER_ID start with 1 increment by 1 noorder;

-- ---------------------------------------------------------------- file formats
CREATE FILE FORMAT IF NOT EXISTS {{database}}.CORE.PARQUET_SNAPPY
	TYPE = PARQUET
	NULL_IF = ()
	COMPRESSION = SNAPPY
COMMENT='Staged share landing: Snappy-compressed Parquet'
;
CREATE FILE FORMAT IF NOT EXISTS {{database}}.CORE.PROFILE_JSON_FORMAT
	TYPE = JSON
	NULL_IF = ()
COMMENT='One table profile document per staged file'
;
CREATE FILE FORMAT IF NOT EXISTS {{database}}.CORE.RAW_TEXT_FORMAT
	RECORD_DELIMITER = 'NONE'
	FIELD_DELIMITER = 'NONE'
	ESCAPE_UNENCLOSED_FIELD = 'NONE'
	REPLACE_INVALID_CHARACTERS = TRUE
COMMENT='Read a whole text file as one value (git skeleton fetch)'
;

-- ---------------------------------------------------------------- stages
CREATE STAGE IF NOT EXISTS {{database}}.CORE.CODE_STAGE DIRECTORY = (ENABLE = TRUE) COMMENT = 'Versioned Python packages imported by platform stored procedures';
CREATE STAGE IF NOT EXISTS {{database}}.CORE.SKILL_STAGE COMMENT = 'Versioned agent skills: <skill>/<version>/SKILL.md';
CREATE STAGE IF NOT EXISTS {{database}}.CORE.DBT_STAGE COMMENT = 'Generated dbt projects: <run_id>/v<generation_version>/...';
CREATE STAGE IF NOT EXISTS {{database}}.CORE.PROFILES_STAGE ENCRYPTION = (TYPE = 'SNOWFLAKE_SSE') DIRECTORY = (ENABLE = TRUE) FILE_FORMAT = (TYPE = 'JSON') COMMENT = 'Table profiles: <SOURCE>/<DATABASE>/<SCHEMA>/<TABLE>.json';
CREATE STAGE IF NOT EXISTS {{database}}.CORE.LANDING_STAGE ENCRYPTION = (TYPE = 'SNOWFLAKE_SSE') FILE_FORMAT = {{database}}.CORE.PARQUET_SNAPPY COMMENT = 'Staged share landing: runs/<run_id>/<table>/ Parquet parts';
CREATE STAGE IF NOT EXISTS {{database}}.CORE.DOCUMENT_FILES ENCRYPTION = (TYPE = 'SNOWFLAKE_SSE') DIRECTORY = (ENABLE = TRUE) COMMENT = 'Original files uploaded to a domain as knowledge sources (Sources tab).';

-- ---------------------------------------------------------------- tables (referenced tables first)
CREATE TABLE IF NOT EXISTS {{database}}.CORE.ACTION_LOG (
	ACTION_ID VARCHAR(36) NOT NULL,
	ISSUE_KEY VARCHAR(64) NOT NULL,
	CLOUD_ID VARCHAR(64),
	RUN_ID VARCHAR(36),
	ACTION VARCHAR(32) NOT NULL,
	DETAIL VARIANT,
	STATUS VARCHAR(16) NOT NULL,
	ERROR VARCHAR(2000),
	ACTED_BY VARCHAR(256) DEFAULT CURRENT_USER(),
	ACTED_AT TIMESTAMP_LTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	ACTOR_KIND VARCHAR(8) DEFAULT 'USER',
	IDEMPOTENCY_KEY VARCHAR(64),
	constraint PK_JIRA_ACTION_LOG primary key (ACTION_ID)
);
CREATE TABLE IF NOT EXISTS {{database}}.CORE.AGENT_RUN (
	AGENT_RUN_ID VARCHAR(36) NOT NULL,
	RUN_ID VARCHAR(36),
	THREAD_ID VARCHAR(64),
	AGENT_NAME VARCHAR(128) NOT NULL,
	PARENT_AGENT VARCHAR(128),
	MODEL VARCHAR(128),
	PROMPT_VERSION VARCHAR(64),
	SKILL_VERSION VARCHAR(64),
	KNOWLEDGE_VERSION VARCHAR(64),
	STATUS VARCHAR(16) NOT NULL,
	STARTED_AT TIMESTAMP_LTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	COMPLETED_AT TIMESTAMP_LTZ(9),
	TOKENS NUMBER(12,0),
	ERROR VARCHAR(4000),
	RESULT_SUMMARY VARCHAR(4000),
	INITIATED_BY VARCHAR(256),
	constraint PK_AGENT_RUN primary key (AGENT_RUN_ID)
);
CREATE TABLE IF NOT EXISTS {{database}}.CORE.AGENT_TOOL_CALL (
	TOOL_CALL_ID VARCHAR(36) NOT NULL,
	AGENT_RUN_ID VARCHAR(36),
	RUN_ID VARCHAR(36),
	TOOL_NAME VARCHAR(128) NOT NULL,
	INPUT_JSON VARIANT,
	OUTPUT_SUMMARY VARCHAR(4000),
	STATUS VARCHAR(16) NOT NULL,
	DURATION_MS NUMBER(12,0),
	QUERY_ID VARCHAR(64),
	ERROR VARCHAR(4000),
	CALLED_BY VARCHAR(256),
	CREATED_AT TIMESTAMP_LTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	constraint PK_AGENT_TOOL_CALL primary key (TOOL_CALL_ID)
);
CREATE TABLE IF NOT EXISTS {{database}}.CORE.AIRFLOW_ENV (
	ENV_ID VARCHAR(64) NOT NULL,
	NAME VARCHAR(120) NOT NULL,
	KIND VARCHAR(16) DEFAULT 'MWAA',
	MWAA_ENV VARCHAR(256) NOT NULL,
	REGION VARCHAR(32) NOT NULL,
	AIRFLOW_URL VARCHAR(1024),
	API_VERSION VARCHAR(8),
	AIRFLOW_VERSION VARCHAR(32),
	ENABLED BOOLEAN DEFAULT TRUE,
	POLL_SECONDS NUMBER(6,0) DEFAULT 300,
	PUSH_ENABLED BOOLEAN DEFAULT FALSE,
	PUSH_SECRET BINARY(8388608),
	WEBHOOK_SECRET_NAME VARCHAR(512),
	LAST_POLL_AT TIMESTAMP_LTZ(9),
	LAST_ATTEMPT_AT TIMESTAMP_LTZ(9),
	CURSOR_VALUE VARCHAR(64),
	LAST_ERROR VARCHAR(2000),
	CREATED_BY VARCHAR(256) DEFAULT CURRENT_USER(),
	CREATED_AT TIMESTAMP_LTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	UPDATED_AT TIMESTAMP_LTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	constraint PK_OPS_AIRFLOW_ENV primary key (ENV_ID)
);
CREATE TABLE IF NOT EXISTS {{database}}.CORE.AI_SUGGESTION (
	SUGGESTION_ID VARCHAR(36) NOT NULL,
	STAGE VARCHAR(32) NOT NULL,
	SCOPE_KEY VARCHAR(1024) NOT NULL,
	FINGERPRINT VARCHAR(64) NOT NULL,
	MODEL VARCHAR(128),
	PROMPT_VERSION NUMBER(6,0) NOT NULL,
	ITEMS VARIANT,
	RUN_ID VARCHAR(36),
	CREATED_BY VARCHAR(256) DEFAULT CURRENT_USER(),
	CREATED_AT TIMESTAMP_LTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	constraint PK_AI_SUGGESTION primary key (SUGGESTION_ID)
);
CREATE TABLE IF NOT EXISTS {{database}}.CORE.AI_SUGGESTION_DECISION (
	DECISION_ID VARCHAR(36) NOT NULL,
	SUGGESTION_ID VARCHAR(36) NOT NULL,
	STAGE VARCHAR(32) NOT NULL,
	SCOPE_KEY VARCHAR(1024) NOT NULL,
	ITEM_KEY VARCHAR(1024) NOT NULL,
	DECISION VARCHAR(16) NOT NULL,
	ITEM VARIANT,
	RUN_ID VARCHAR(36),
	DOMAIN_ID VARCHAR(64),
	NOTE VARCHAR(2000),
	DECIDED_BY VARCHAR(256) DEFAULT CURRENT_USER(),
	DECIDED_AT TIMESTAMP_LTZ(9) DEFAULT CURRENT_TIMESTAMP(),
