CREATE TABLE IF NOT EXISTS {{database}}.CORE.CASE_RECORD cluster by (STATUS, DOMAIN_ID)(
	CASE_ID VARCHAR(36) NOT NULL,
	CASE_NUMBER NUMBER(12,0) DEFAULT {{database}}.CORE.CASE_SEQ.NEXTVAL,
	DOMAIN_ID VARCHAR(36),
	TITLE VARCHAR(300) NOT NULL,
	DESCRIPTION VARCHAR(20000),
	KIND VARCHAR(16) NOT NULL,
	SOURCE VARCHAR(16) NOT NULL,
	SOURCE_REF VARCHAR(500),
	PAGE_CONTEXT VARIANT,
	STATUS VARCHAR(16) NOT NULL,
	SEVERITY VARCHAR(2) NOT NULL,
	ASSIGNEE VARCHAR(256),
	TEAM_ID VARCHAR(64),
	SLA_DUE_AT TIMESTAMP_LTZ(9),
	TARGET_TABLE_ID VARCHAR(36),
	RUN_ID VARCHAR(36),
	REPO_ID VARCHAR(64),
	MODELS ARRAY,
	FINGERPRINT VARCHAR(40),
	AI VARIANT,
	AI_SUMMARY VARCHAR(2000),
	DUPLICATE_OF VARCHAR(36),
	RESOLUTION VARCHAR(4000),
	RESOLVED_BY VARCHAR(256),
	RESOLVED_AT TIMESTAMP_LTZ(9),
	CLOSED_AT TIMESTAMP_LTZ(9),
	REOPENED NUMBER(6,0) DEFAULT 0,
	OPENED_BY VARCHAR(256) DEFAULT CURRENT_USER(),
	OPENED_AT TIMESTAMP_LTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	UPDATED_AT TIMESTAMP_LTZ(9) DEFAULT CURRENT_TIMESTAMP(),
