CREATE TABLE IF NOT EXISTS {{database}}.CORE.DAG (
	ENV_ID VARCHAR(64) NOT NULL,
	DAG_ID VARCHAR(250) NOT NULL,
	FILELOC VARCHAR(2000),
	OWNERS ARRAY,
