	KIND VARCHAR(16) NOT NULL,
	ORDINAL NUMBER(6,0) NOT NULL,
	PHASE NUMBER(2,0) NOT NULL,
	ENABLED BOOLEAN NOT NULL,
	RETRY_TO VARCHAR(64) NOT NULL,
	GRAPH_VERSION VARCHAR(32) NOT NULL,
	UPDATED_AT TIMESTAMP_LTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	constraint PK_WORKFLOW_STATE primary key (STATE)
);
CREATE TABLE IF NOT EXISTS {{database}}.CORE.WORKFLOW_TRANSITION (
	FROM_STATE VARCHAR(64) NOT NULL,
	TO_STATE VARCHAR(64) NOT NULL,
	ACTOR VARCHAR(16) NOT NULL,
	GUARD VARCHAR(64),
	ENABLED BOOLEAN NOT NULL,
	GRAPH_VERSION VARCHAR(32) NOT NULL,
	UPDATED_AT TIMESTAMP_LTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	constraint PK_WORKFLOW_TRANSITION primary key (FROM_STATE, TO_STATE)
);

-- ---------------------------------------------------------------- row access policies and attachments
CREATE ROW ACCESS POLICY IF NOT EXISTS {{database}}.CORE.COPILOT_OWN_ROWS as (ROW_USER VARCHAR) 
returns BOOLEAN ->
ROW_USER = CURRENT_USER() OR IS_DATABASE_ROLE_IN_SESSION('PLATFORM_ADMIN')
COMMENT='Copilot sessions, events, plan steps, drafted changes and attachments are visible only to the person who created them (and platform admins)'
;
ALTER TABLE {{database}}.CORE.COPILOT_ATTACHMENT DROP ALL ROW ACCESS POLICIES;
ALTER TABLE {{database}}.CORE.COPILOT_ATTACHMENT ADD ROW ACCESS POLICY {{database}}.CORE.COPILOT_OWN_ROWS ON (CREATED_BY);
ALTER TABLE {{database}}.CORE.COPILOT_CHANGE DROP ALL ROW ACCESS POLICIES;
ALTER TABLE {{database}}.CORE.COPILOT_CHANGE ADD ROW ACCESS POLICY {{database}}.CORE.COPILOT_OWN_ROWS ON (CREATED_BY);
ALTER TABLE {{database}}.CORE.COPILOT_EVENT DROP ALL ROW ACCESS POLICIES;
ALTER TABLE {{database}}.CORE.COPILOT_EVENT ADD ROW ACCESS POLICY {{database}}.CORE.COPILOT_OWN_ROWS ON (CREATED_BY);
ALTER TABLE {{database}}.CORE.COPILOT_PLAN_STEP DROP ALL ROW ACCESS POLICIES;
ALTER TABLE {{database}}.CORE.COPILOT_PLAN_STEP ADD ROW ACCESS POLICY {{database}}.CORE.COPILOT_OWN_ROWS ON (CREATED_BY);
ALTER TABLE {{database}}.CORE.COPILOT_SESSION DROP ALL ROW ACCESS POLICIES;
ALTER TABLE {{database}}.CORE.COPILOT_SESSION ADD ROW ACCESS POLICY {{database}}.CORE.COPILOT_OWN_ROWS ON (CREATED_BY);
CREATE ROW ACCESS POLICY IF NOT EXISTS {{database}}.CORE.DOMAIN_SCOPE as (ROW_DOMAIN VARCHAR) 
returns BOOLEAN ->
ROW_DOMAIN IS NULL
    OR IS_DATABASE_ROLE_IN_SESSION('PLATFORM_ADMIN')
    OR ROW_DOMAIN IN (SELECT DOMAIN_ID FROM {{database}}.CORE.DOMAIN_REGISTRY WHERE UPPER(DOMAIN_NAME) = 'GENERAL')
    OR ROW_DOMAIN IN (SELECT DOMAIN_ID FROM {{database}}.CORE.DOMAIN_MEMBER WHERE UPPER(USER_NAME) = UPPER(CURRENT_USER()))
    OR ROW_DOMAIN NOT IN (SELECT DOMAIN_ID FROM {{database}}.CORE.DOMAIN_MEMBER)
COMMENT='A case is visible in GENERAL, to members of its domain, in a domain without members, and to platform admins'
;
ALTER TABLE {{database}}.CORE.CASE_RECORD DROP ALL ROW ACCESS POLICIES;
ALTER TABLE {{database}}.CORE.CASE_RECORD ADD ROW ACCESS POLICY {{database}}.CORE.DOMAIN_SCOPE ON (DOMAIN_ID);
CREATE ROW ACCESS POLICY IF NOT EXISTS {{database}}.CORE.OWN_ROWS as (ROW_USER VARCHAR) 
returns BOOLEAN ->
ROW_USER = CURRENT_USER() OR IS_DATABASE_ROLE_IN_SESSION('PLATFORM_ADMIN')
COMMENT='Jira token and sign-in rows are visible and writable only by their own user (and platform admins)'
;
ALTER TABLE {{database}}.CORE.OAUTH_STATE DROP ALL ROW ACCESS POLICIES;
ALTER TABLE {{database}}.CORE.OAUTH_STATE ADD ROW ACCESS POLICY {{database}}.CORE.OWN_ROWS ON (USER_NAME);
ALTER TABLE {{database}}.CORE.USER_TOKEN DROP ALL ROW ACCESS POLICIES;
ALTER TABLE {{database}}.CORE.USER_TOKEN ADD ROW ACCESS POLICY {{database}}.CORE.OWN_ROWS ON (USER_NAME);

-- ---------------------------------------------------------------- views
create or replace view {{database}}.CORE.PERSISTENT_PROFILES(
	PROFILE_ID,
	SOURCE_NAME,
	DATABASE_NAME,
	SCHEMA_NAME,
	TABLE_NAME,
	COLUMN_NAME,
	ORDINAL,
	RUN_ID,
	DOMAIN_ID,
	DATA_TYPE,
	FAMILY,
	SEMANTIC_TYPE,
	PII_CLASSIFICATION,
	ROW_COUNT,
	NULL_COUNT,
	NULL_PCT,
	DISTINCT_COUNT,
	CARDINALITY,
	CARDINALITY_RATIO,
	MIN_VALUE,
	MAX_VALUE,
	POTENTIAL_KEY,
	TOP_VALUES,
	HISTOGRAM,
	DESCRIPTION,
	IS_APPROXIMATE,
	PROFILER_VERSION,
	PROFILED_BY,
	PROFILED_AT
) COMMENT='Alias of CORE.DATA_PROFILES'
 as SELECT * FROM {{database}}.CORE.DATA_PROFILES;

